async function api(path,method='GET',data){if(path==='/assistant'&&config.aiProvider==='gemini'){if(!geminiConsent){geminiConsent=!!await confirmAction('Google Gemini ilə davam edək?','Yazdığınız mətn Google Gemini-yə göndərilir. Pulsuz xidmətdə Google məzmunu məhsullarını təkmilləşdirmək üçün istifadə edə bilər. Şəxsi və məxfi məlumat yazmayın.');if(!geminiConsent)throw Error('Mesaj göndərilmədi.');}data={...data,consent:true};}const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let b;try{b=await r.json();}catch{throw new Error('Xidmətlə əlaqə qurulmadı. Səhifəni yeniləyin.');}if(!r.ok){const e=new Error(b.error||'Əməliyyat baş tutmadı.');e.status=r.status;throw e;}return b;}
async function task(button,fn){if(button)button.disabled=true;try{return await fn();}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}}
