 main.innerHTML=`<div class="layout">${sidebar()}<section><p class="eyebrow">İdarəetmə</p><h1 style="font-size:2rem">Platformaya ümumi baxış</h1><div id="admin-content">${loader()}</div></section></div>`;wireLogout();
